INSERT INTO estate_transactions (source_row_number, receipt_year, district_code, district_name, legal_dong_code, legal_dong_name, lot_type_code, lot_type_name, main_lot_number, sub_lot_number, building_name, contract_date, deal_amount_10k_krw, building_area_square_meter, land_area_square_meter, floor, right_type, canceled_at, built_year, building_use, report_type, brokered_agent_sgg_name)
SELECT source_row_number, receipt_year, district_code, district_name, legal_dong_code, legal_dong_name, lot_type_code, lot_type_name, main_lot_number, sub_lot_number, building_name, contract_date, deal_amount_10k_krw, building_area_square_meter, land_area_square_meter, floor, right_type, canceled_at, built_year, building_use, report_type, brokered_agent_sgg_name
FROM estate_transactions_staging
ON CONFLICT (source_row_number) DO UPDATE
SET
    receipt_year = EXCLUDED.receipt_year,
    district_code = EXCLUDED.district_code,
    district_name = EXCLUDED.district_name,
    legal_dong_code = EXCLUDED.legal_dong_code,
    legal_dong_name = EXCLUDED.legal_dong_name,
    lot_type_code = EXCLUDED.lot_type_code,
    lot_type_name = EXCLUDED.lot_type_name,
    main_lot_number = EXCLUDED.main_lot_number,
    sub_lot_number = EXCLUDED.sub_lot_number,
    building_name = EXCLUDED.building_name,
    contract_date = EXCLUDED.contract_date,
    deal_amount_10k_krw = EXCLUDED.deal_amount_10k_krw,
    building_area_square_meter = EXCLUDED.building_area_square_meter,
    land_area_square_meter = EXCLUDED.land_area_square_meter,
    floor = EXCLUDED.floor,
    right_type = EXCLUDED.right_type,
    canceled_at = EXCLUDED.canceled_at,
    built_year = EXCLUDED.built_year,
    building_use = EXCLUDED.building_use,
    report_type = EXCLUDED.report_type,
    brokered_agent_sgg_name = EXCLUDED.brokered_agent_sgg_name
;

SELECT setval(
    pg_get_serial_sequence('estate_transactions', 'id'),
    GREATEST(COALESCE(MAX(id), 1), 1),
    COALESCE(MAX(id), 0) > 0
)
FROM estate_transactions;
